mapper.select:
SELECT SHOPPING_NO
FROM SHOPPING_LIST
WHERE USER_NO = #{userNo}
  AND BOARD_NO = #{boardNo}
LIMIT 1

mapper.delete:
DELETE FROM SHOPPING_LIST
WHERE SHOPPING_NO = #{shoppingNo}
  AND USER_NO = #{userNo}

DELETE FROM SHOPPING_ITEM
WHERE SHOPPING_NO IN (
    SELECT SHOPPING_NO
    FROM SHOPPING_LIST
    WHERE SHOPPING_NO = #{shoppingNo}
      AND USER_NO = #{userNo}
)
